export const levelingImageCanvasSchema = z
	.object({
		width: z.number(),
		height: z.number(),
		background_color: z.string().nullable(),
		background_url: z.string().nullable(),
		background_fit: z.enum(["cover", "contain", "fill"]).nullable(),
		elements: z.preprocess(
			(v) => (v == null ? [] : v),
			z.array(levelingImageElementSchema),
		),
	})
	.default(DEFAULT_LEVELING_CARD_CANVAS);

// ─── Módulo completo (leveling-v3.md §2) ─────────────────────────────────────

/**
 * Config POR-GUILD del módulo de niveles (XP y rangos). El almacenamiento de
 * XP vive SIEMPRE en Postgres (`leveling.user_stats`, `text_xp`/`voice_xp`
 * separados); este documento es sólo la CONFIGURACIÓN.
 *
 * `xp_mode` es la PRIMERA decisión del admin y de ella depende la forma
 * entera de la interfaz. Cambiarla en el dashboard NUNCA destruye
 * configuración ni recalcula nada en masa (recálculo perezoso): los CUATRO
 * bloques (`text`, `voice`, `progression_text`, `progression_voice`) se
 * persisten SIEMPRE, los use o no el modo activo. Qué bloque es el EFECTIVO
 * para cada modo es una regla ÚNICA — no reimplementar el switch en el
 * resto de componentes, usar `resolveLevelingScope`/`levelingProgressionFor`:
 *
 * | Modo         | Fuentes que conceden | Progresión(es) efectiva(s)                    |
 * |--------------|-----------------------|------------------------------------------------|
 * | `text_only`  | `text`                | `progression_text`                              |
 * | `voice_only` | `voice`               | `progression_voice`                             |
 * | `unified`    | `text` y `voice`      | `progression_text` (nivel = text_xp + voice_xp) |
 * | `separate`   | `text` y `voice`      | `progression_text` / `progression_voice`        |
 *
 * ⚠️ En `unified` la progresión activa es `progression_text` — deliberado:
 * evita un tercer bloque que sólo existiría para ese modo y hace que pasar de
 * `unified` a `separate` conserve la curva y las recompensas ya configuradas
 * (la de voz arranca con sus propios defaults). La interfaz NO llama a ese
 * bloque "Texto" en modo `unified`, lo llama "Progresión"
 * (`LEVELING_MODE_PROGRESSIONS`/`levelingProgressionLabelKey`).
 */
export interface DBModuleLeveling {
	schema_version: number;
	enabled: boolean;
	/** Fecha de la PRIMERA activación (ISO-8601 UTC). WRITE-ONCE server-side:
	 *  el dashboard nunca la edita (ver `ModuleLevelingSchema`/`LEVELING_SKIP`). */
	enabled_since: string | null;
	xp_mode: LevelingXpMode;
	/** Reglas de concesión de XP por mensaje. Se persiste aunque el modo activo no la use. */
	text: DBLevelingSource;
	/** Reglas de concesión de XP por tiempo en voz. Se persiste aunque el modo activo no la use. */
	voice: DBLevelingSource;
	/** Progresión de texto. En `unified` es también la ÚNICA progresión activa (ver TSDoc de arriba). */
	progression_text: DBLevelingProgression;
	/** Progresión de voz. Efectiva sólo en `voice_only` y `separate`; se persiste igual en los demás modos. */
	progression_voice: DBLevelingProgression;
	/** Tarjeta ÚNICA de `/rank`; el ámbito con el que se invoque decide qué datos rellenan sus tokens (spec §3). */
	rank_card: {
		mode: LevelingCardMode;
		/** Modo `basic`: fondo y acento de la tarjeta de fábrica. */
		background_url: string | null;
		accent_color: string;
		/** Modo `advanced`: lienzo del editor. */
		canvas: DBLevelingImageCanvas;
	};
	/** Acceso GLOBAL de los comandos del módulo (mismo tipo que tempvoice). */
	commands_global: DBCommandAccess;
	/** Config por comando. Clave = nombre del comando (`rank`, `xp`, `top`). */
	commands: Record<string, DBLevelingCommand>;
	command_mode: LevelingCommandMode;
	updated_at: Date;
}

// `updated_at` lo estampa api-db en cada escritura: el dashboard no tiene
// ningún control que lo lea ni lo edite, así que se excluye del tipo que
// consume el formulario — igual que tempvoice ("`updated_at` lo gestiona el
// backend; se omite en el dashboard"). A diferencia de tts/greeter/notifier/
// giveaways, que sí lo traen para poder re-parsearlo con `z.coerce.date()`,
// aquí no hay ninguna superficie que lo necesite.
export type ModuleLevelingSchema = Omit<DBModuleLeveling, "updated_at">;

export const moduleLevelingSchema = createZodObject<ModuleLevelingSchema>({
	schema_version: z.number(),
	enabled: z.boolean(),
	// Write-once server-side; nunca se edita desde el PATCH (ver LEVELING_SKIP
	// en LevelingForm.tsx y el `.omit` de abajo).
	enabled_since: z.string().nullable(),
	xp_mode: z.enum(LEVELING_XP_MODES),
	text: levelingSourceSchema,
	voice: levelingSourceSchema,
	progression_text: levelingProgressionSchema,
	progression_voice: levelingProgressionSchema,
	rank_card: z.object({
		mode: z.enum(LEVELING_CARD_MODES),
		background_url: z.string().nullable(),
		accent_color: z.string(),
		canvas: levelingImageCanvasSchema,
	}),
	commands_global: commandAccessSchema,
	commands: z.record(z.string(), levelingCommandSchema),
	command_mode: z.enum(LEVELING_COMMAND_MODES),

package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// UpdateModuleLevelingBody es el cuerpo PATCH estricto del módulo de
// niveles — mismo molde que `UpdateModuleTempvoiceBody`: todos los campos
// son punteros para que el decodificador estricto (`DisallowUnknownFields`)
// valide la forma mientras la PRESENCIA de la clave sobrevive para el merge
// `MergeDeepJSON` del repositorio: una clave ausente en el body no se toca;
// un `false`/`0`/`""`/`null` explícito se aplica y pisa el valor guardado;
// los objetos anidados recursan (un PATCH parcial de `{"text":{"min":10}}`
// conserva el resto de `text` intacto); el único mapa (`commands`) mezcla
// por clave.
//
// `schema_version`, `enabled_since` y `updated_at` quedan FUERA a propósito
// — son gestionados por el servidor (mismo criterio que
// `UpdateModuleTempvoiceBody`: `enabled_since` es WRITE-ONCE y ni siquiera se
// acepta como clave, así que un cliente que la mande recibe 400 por clave
// desconocida en vez de que se ignore en silencio).
type UpdateModuleLevelingBody struct {
	Enabled            *bool                                `json:"enabled,omitempty"`
	XPMode             *dbguild.LevelingXPMode              `json:"xp_mode,omitempty"`
	Text               *dbguild.LevelingXpSource            `json:"text,omitempty"`
	Voice              *dbguild.LevelingXpSource            `json:"voice,omitempty"`
	CurveMultiplier    *float64                             `json:"curve_multiplier,omitempty"`
	VoiceRules         *dbguild.LevelingVoiceRules          `json:"voice_rules,omitempty"`
	ExcludedChannelIDs *[]string                            `json:"excluded_channel_ids,omitempty"`
	ExcludedRoleIDs    *[]string                            `json:"excluded_role_ids,omitempty"`
	RoleMultipliers    *[]dbguild.LevelingMultiplier        `json:"role_multipliers,omitempty"`
	ChannelMultipliers *[]dbguild.LevelingMultiplier        `json:"channel_multipliers,omitempty"`
	Announce           *dbguild.LevelingAnnounce            `json:"announce,omitempty"`
	Rewards            *dbguild.LevelingRewards             `json:"rewards,omitempty"`
	RankCard           *dbguild.LevelingRankCard            `json:"rank_card,omitempty"`
	CommandsGlobal     *dbguild.LevelingCommandAccess        `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.LevelingCommand   `json:"commands,omitempty"`
	CommandMode        *dbguild.LevelingCommandMode          `json:"command_mode,omitempty"`
}

package handlers

import (
	"bytes"
	"encoding/json"

	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
	"kena.bot/api-db-go/internal/domain/validations"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
	"kena.bot/api-db-go/internal/shared/result"
)

// sourceDetailLevelingDBNotFound es el detalle de fuente estampado en el
// envelope de "no encontrado" del PATCH (el repo devuelve un `nil` a secas
// ahí, así que el handler no tiene un `Sourced` del que leerlo). Se
// mantiene en paralelo con `mongo.SourceDetailModuleLevelingDB` — el
// handler no puede importar el paquete de infraestructura mongo sin violar
// las capas, así que el string se duplica localmente. Mismo patrón que
// `sourceDetailTicketsDBNotFound`.
const sourceDetailLevelingDBNotFound = "mongo.guild.module_leveling"

// ModuleLevelingHandler cablea los dos endpoints de niveles (GET/PATCH
// scoped a guild) tras un único struct. Espeja al handler de tickets:
// payload `*dbguild.ModuleLeveling` para que los caminos "no encontrado"
// emitan `"data":null`, sin pre-chequeo de guild (una guild ausente da
// MODULE_NOT_FOUND, no GUILD_NOT_FOUND).
type ModuleLevelingHandler struct {
	Repo mongorepo.ModuleLevelingRepo
}

// NewModuleLevelingHandler construye el handler.
func NewModuleLevelingHandler(repo mongorepo.ModuleLevelingRepo) *ModuleLevelingHandler {
	return &ModuleLevelingHandler{Repo: repo}
}

// Get devuelve el subdocumento de niveles completo (con defaults y
// normalizado) con las cabeceras de fuente estampadas, o un 400
// MODULE_NOT_FOUND con `data:null` + fuente cuando la guild todavía no
// tiene config de niveles.
func (h *ModuleLevelingHandler) Get(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleLeveling]()
	ctx := c.Context()

	sourced, err := h.Repo.FindModule(ctx, c.Params("bot_id"), c.Params("guild_id"))
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced != nil {
		r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	return reply(c, r)
}

// Patch valida el body estricto (`DisallowUnknownFields`), lo redecodifica
// como `map[string]any` para que la PRESENCIA de claves sobreviva, y el
// repo lo mezcla con `MergeDeepJSON` sobre el subdocumento actual. Un body
// vacío `{}` es un no-op que igualmente bumpea `schema_version`. Una guild
// ausente → 400 MODULE_NOT_FOUND con `data:null`.
func (h *ModuleLevelingHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleLeveling]()
	ctx := c.Context()

	var body validations.UpdateModuleLevelingBody
	dec := json.NewDecoder(bytes.NewReader(c.Body()))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), patch)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		r.SetSource(result.SourceDB, sourceDetailLevelingDBNotFound)
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

package mongo

import (
	"context"
	stderrors "errors"
	"fmt"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"

	"kena.bot/api-db-go/internal/domain/dbguild"
	"kena.bot/api-db-go/internal/domain/mocks"
	"kena.bot/api-db-go/internal/infrastructure/locker"
	"kena.bot/api-db-go/internal/infrastructure/redis"
)

// ModuleLevelingRepository es el dueño de las lecturas/escrituras contra el
// subdocumento `module_leveling` de la colección `guilds`, más su caché
// Redis dedicada.
//
// Layout de caché (igual que el resto de módulos):
//
//	bots:{botId}:guilds:{guildId}:modules:leveling    HASH (TTL: ModuleTTLSeconds)
//
// Molde EXACTO de `ModuleTicketsRepository`: sin `force` (el módulo nace
// hoy, no hay ningún `?force` heredado de Node que replicar), lectura
// cache-first con fallback a Mongo proyectando sólo el subdocumento, y
// escritura MergeDeepJSON read-merge-write serializada por guild.
const (
	SourceDetailModuleLevelingCache = "redis:cache.db.module"
	SourceDetailModuleLevelingDB    = "mongo.guild.module_leveling"
)

// ModuleLevelingRepository es la fachada específica de niveles. Misma
// estructura caché+locker que greeter/tickets/tempvoice.
type ModuleLevelingRepository struct {
	coll  *mongo.Collection
	cache *redis.ModuleCache
	lk    *locker.Locker
}

func (r *ModuleLevelingRepository) WithLocker(lk *locker.Locker) *ModuleLevelingRepository {
	r.lk = lk
	return r
}

func (r *ModuleLevelingRepository) lockKey(key string) func() {
	if r.lk != nil {
		return r.lk.Lock(key)
	}
	return locker.LocalOnly(key)
}

// NewModuleLevelingRepository conecta la caché + la colección.
func NewModuleLevelingRepository(db *mongo.Database, cache *redis.ModuleCache) *ModuleLevelingRepository {
	return &ModuleLevelingRepository{
		coll:  db.Collection("guilds"),
		cache: cache,
	}
}

// FindModule devuelve el subdocumento de niveles, cache-first. En un fallo de
// caché cae a Mongo con una proyección de `module_leveling`, rellena los
// campos que falten vía `mocks.NewModuleLeveling()`, normaliza las
// colecciones vacías, y escribe el resultado en caché con
// TTL=ModuleTTLSeconds.
func (r *ModuleLevelingRepository) FindModule(ctx context.Context, botID, guildID string) (*Sourced[dbguild.ModuleLeveling], error) {
	// Camino rápido de caché.
	if cached, err := r.cache.GetModule(ctx, botID, guildID, "leveling"); err == nil && cached != nil {
		var m dbguild.ModuleLeveling
		if err := mapToModuleLeveling(cached, &m); err == nil && m.SchemaVersion != 0 {
			dbguild.NormalizeLeveling(&m)
			return &Sourced[dbguild.ModuleLeveling]{
				Data:         m,
				Source:       "cache",
				SourceDetail: SourceDetailModuleLevelingCache,
			}, nil
		}
		// Fallo de parseo o schema desactualizado → se descarta y se relee.
		_ = r.cache.DeleteModule(ctx, botID, guildID, "leveling")
	}

	// Camino lento: proyecta sólo el bloque module_leveling.
	filter := bson.M{"bot_id": botID, "guild_id": guildID}
	projection := bson.M{"module_leveling": 1}
	var out struct {
		ModuleLeveling dbguild.ModuleLeveling `bson:"module_leveling"`
	}
	if err := r.coll.FindOne(ctx, filter, options.FindOne().SetProjection(projection)).Decode(&out); err != nil {
		if stderrors.Is(err, mongo.ErrNoDocuments) {
			return &Sourced[dbguild.ModuleLeveling]{
				Data:         dbguild.ModuleLeveling{},
				Source:       "db",
				SourceDetail: SourceDetailModuleLevelingDB,
			}, nil
		}
		return nil, err
	}

	m := out.ModuleLeveling
	if m.SchemaVersion == 0 {
		m = mocks.NewModuleLeveling()
	}
	dbguild.NormalizeLeveling(&m)

	if fields, err := redis.MarshalModuleLeveling(m); err == nil {
		_ = r.cache.SetModule(ctx, botID, guildID, "leveling", fields, redis.ModuleTTLSeconds)
	}

	return &Sourced[dbguild.ModuleLeveling]{
		Data:         m,
		Source:       "db",
		SourceDetail: SourceDetailModuleLevelingDB,
	}, nil
}

// Update aplica el body parcial al subdocumento de niveles vía
// `MergeDeepJSON` (recursivo, basado en presencia): un body con `text.min`
// sólo toca esa hoja, `commands` mezcla por clave (nombre del comando), los
// slices (`role_multipliers`, `rewards.levels`, …) se reemplazan enteros, y
// un `false`/`0`/`null` explícito SE APLICA. Sólo se bumpea `updatedAt` a
// nivel de guild vía `$currentDate`. Una guild inexistente devuelve `nil`
// (el handler lo traduce a 400 MODULE_NOT_FOUND). Serializado por guild.
func (r *ModuleLevelingRepository) Update(ctx context.Context, botID, guildID string, patch map[string]any) (*Sourced[dbguild.ModuleLeveling], error) {
	unlock := r.lockKey("leveling:" + botID + "\x00" + guildID)
	defer unlock()

	filter := bson.M{"bot_id": botID, "guild_id": guildID}
	var before struct {
		ModuleLeveling dbguild.ModuleLeveling `bson:"module_leveling"`
	}
	if err := r.coll.FindOne(ctx, filter).Decode(&before); err != nil {
		if stderrors.Is(err, mongo.ErrNoDocuments) {
			return nil, nil
		}
		return nil, fmt.Errorf("module leveling update (pre-read): %w", err)
	}

	// Se mezcla sobre una copia para que la vista del llamador nunca quede a
	// medio mezclar.
	merged := before.ModuleLeveling
	if merged.SchemaVersion == 0 {
		merged = mocks.NewModuleLeveling()
	}
	if err := MergeDeepJSON(&merged, patch); err != nil {
		return nil, fmt.Errorf("module leveling update (merge): %w", err)
	}
	// El `updated_at` PROPIO del módulo se estampa a `now` DESPUÉS de la
	// mezcla — el body estricto del PATCH rechaza la clave, así que nunca
	// llega en `patch`.
	merged.UpdatedAt = dbguild.NewDate(time.Now().UTC().Truncate(time.Millisecond))
	// Se estampa `schema_version` directo sobre el struct mezclado para no
	// chocar con el `module_leveling` del mismo `$set`.
	merged.SchemaVersion = dbguild.SchemaVersionLeveling
	// Garantiza que las colecciones vacías sigan no-nil ([] / {}) tras la
	// mezcla.
	dbguild.NormalizeLeveling(&merged)

	// `enabled_since` es WRITE-ONCE y EXCLUSIVAMENTE server-side. Se
	// restaura primero el valor ALMACENADO, pisando lo que la mezcla haya
	// podido dejar — el body estricto ya rechaza la clave, esto es defensa
	// en profundidad.
	merged.EnabledSince = before.ModuleLeveling.EnabledSince

	// Se estampa la PRIMERA vez que el módulo queda activado y no se
	// reescribe nunca: desactivar no lo borra y reactivar no lo pisa.
	if merged.Enabled && merged.EnabledSince == nil {
		stamp := dbguild.NewDate(time.Now().UTC().Truncate(time.Millisecond))
		merged.EnabledSince = &stamp
	}

	update := bson.M{
		"$set": bson.M{
			"module_leveling": merged,
		},
		"$currentDate": bson.M{"updatedAt": true},
	}
	opt := options.FindOneAndUpdate().SetReturnDocument(options.After)
	opt = opt.SetProjection(bson.M{"module_leveling": 1})
	var after struct {
		ModuleLeveling dbguild.ModuleLeveling `bson:"module_leveling"`
	}
	if err := r.coll.FindOneAndUpdate(ctx, filter, update, opt).Decode(&after); err != nil {
		if stderrors.Is(err, mongo.ErrNoDocuments) {
			return nil, nil
		}
		return nil, fmt.Errorf("module leveling update: %w", err)
	}

	m := after.ModuleLeveling
	dbguild.NormalizeLeveling(&m)

	if fields, err := redis.MarshalModuleLeveling(m); err == nil {
		_ = r.cache.SetModule(ctx, botID, guildID, "leveling", fields, redis.ModuleTTLSeconds)
	}

	// La escritura puede haber cambiado `enabled`, así que el snapshot
	// `enabled_modules` del guild ya no es de fiar. Ver
	// invalidateEnabledSnapshot.
	invalidateEnabledSnapshot(ctx, r.cache, botID, guildID, "leveling")

	return &Sourced[dbguild.ModuleLeveling]{
		Data:         m,
		Source:       "db",
		SourceDetail: SourceDetailModuleLevelingDB,
	}, nil
}

// mapToModuleLeveling deserializa un hash de caché crudo al módulo tipado.
// Best-effort: un fallo de parseo devuelve el error para que el llamador
// invalide la caché y relea de Mongo.
func mapToModuleLeveling(raw map[string]any, out *dbguild.ModuleLeveling) error {
	b, err := bson.Marshal(raw)
	if err != nil {
		return err
	}
	return bson.Unmarshal(b, out)
}

