import type { DBLevelingRequirements } from "@kena/shared";

/**
 * Requisitos de elegibilidad (§2 de leveling-v3.md, TSDoc de `DBLevelingRequirements`
 * en `DBGuildSchemas.ts`): condiciones que un miembro debe cumplir para ganar
 * XP de UNA fuente — cada fuente (texto o voz) lleva su PROPIA copia dentro de
 * `DBLevelingSource`, este fichero no sabe de cuál. Helper PURO — cero
 * peticiones a Discord, a la API ni a Redis: recibe en `ctx` todo lo que el
 * llamante ya tiene a mano (roles, fecha de entrada al servidor, y en texto el
 * propio mensaje), y sólo hace aritmética y comparaciones de string.
 *
 * Dos sitios lo usan, con semántica distinta sobre el RESULTADO (no sobre esta
 * función, que siempre es la misma pregunta: "¿puede ganar XP ahora mismo?"):
 *   - `events/messages/MessageCreate.ts`: se comprueba con `leveling.text.requirements`,
 *     tras las exclusiones de canal/rol y ANTES de consumir el cooldown antispam.
 *   - `shared/voice-ticker.ts` (`resolveSessionCredit`): se comprueba con
 *     `leveling.voice.requirements`, junto al resto de descalificaciones
 *     (`muted`/`deafened`/`alone`) y, como ellas, adelanta el reloj de la sesión.
 */

export type RequirementContext = {
	userId: string;
	roleIds: string[];
	/** ms epoch de entrada al servidor; `null` si la caché no lo tiene. */
	joinedAt: number | null;
	/** Solo texto. `undefined` en voz. */
	message?: { content: string; hasAttachments: boolean; hasStickers: boolean; prefix: string };
};

/** Época de los snowflakes de Discord: 2015-01-01T00:00:00.000Z, en ms. */
const DISCORD_EPOCH_MS = 1_420_070_400_000n;

/**
 * Timestamp (ms epoch) de creación de la CUENTA, deducido del propio snowflake
 * del id de usuario: los 42 bits altos son los ms transcurridos desde
 * `DISCORD_EPOCH_MS` (§2). Cero peticiones — ni a Discord ni a caché.
 *
 * Un `userId` que no parsee como snowflake (dato corrupto; nunca debería pasar
 * con un id real de Discord) cae a la época — cuenta "infinitamente vieja", que
 * SIEMPRE supera cualquier `min_account_age_seconds`. Mismo criterio que
 * `snowflakeToDate` en `moderation-module` y que la caché fría de `joinedAt` más
 * abajo: ante la duda de infraestructura, se concede.
 */
function accountCreatedAtMs(userId: string): number {
	try {
		return Number((BigInt(userId) >> 22n) + DISCORD_EPOCH_MS);
	} catch {
		return 0;
	}
}

/** Emoji custom de Discord: `<:nombre:id>` (estático) o `<a:nombre:id>` (animado). */
const CUSTOM_EMOJI_RE = /<a?:\w+:\d+>/g;

/**
 * Segmentador de grafemas: agrupa una secuencia emoji completa (base + selector
 * de presentación + ZWJ + modificador de tono de piel + bandera + keycap) en UN
 * solo "carácter visual" — que es justo la unidad que hay que clasificar como
 * "emoji" o "no emoji". Trocear por code point suelto rompería, por ejemplo, una
 * bandera (dos code points) o una familia (varios emojis unidos por ZWJ).
 */
const graphemes = new Intl.Segmenter(undefined, { granularity: "grapheme" });

/**
 * ¿Este grafema (ya segmentado) es un emoji unicode? `\p{Extended_Pictographic}`
 * cubre la inmensa mayoría (incluye el emoji base de las secuencias ZWJ/tono de
 * piel, ya fundidas en el mismo grafema por el segmentador de arriba). Aparte,
 * dos familias que esa propiedad NO cubre y sí son emoji real:
 *   - Banderas de país: dos "Regional Indicator" (🇪+🇸 → 🇪🇸), sin ningún code
 *     point pictográfico.
 *   - Keycaps: dígito/`#`/`*` + selector opcional + U+20E3 (1️⃣) — el carácter
 *     base tampoco es pictográfico (a propósito: si lo fuera, un "5" suelto ya
 *     contaría como emoji).
 * Deliberadamente NO se usa `\p{Emoji}` a secas: esa propiedad SÍ marca dígitos,
 * `#` y `*` (participan en keycaps), así que un mensaje "hay 5 sitios libres" se
 * leería como "solo emoji".
 */
function isEmojiGrapheme(cluster: string): boolean {
	if (/\p{Extended_Pictographic}/u.test(cluster)) return true;
	if (/^\p{Regional_Indicator}{2}$/u.test(cluster)) return true;
	if (/^[0-9#*]\uFE0F?\u20E3$/u.test(cluster)) return true;
	return false;
}

/**
 * ¿El contenido (ya recortado, NO vacío) es solo emojis — unicode y/o custom? Quita
 * primero los custom (patrón propio, no son un grafema unicode) y trocea el resto
 * en grafemas: si TODOS son espacio o emoji, es "solo emoji". Vacío tras quitar los
 * custom (ej. `"<:ok:1><:ok:2>"`) cuenta como "solo emoji" trivialmente — no queda
 * ningún grafema que lo contradiga.
 */
function isEmojiOnlyContent(trimmedContent: string): boolean {
	const withoutCustom = trimmedContent.replace(CUSTOM_EMOJI_RE, "");
	for (const { segment } of graphemes.segment(withoutCustom)) {
		if (/^\s+$/.test(segment)) continue;
		if (!isEmojiGrapheme(segment)) return false;
	}
	return true;
}

/** URL con o sin esquema (`https://…`, `www.…`). Heurística simple a propósito: para
 *  decidir "el mensaje es solo un enlace" no hace falta un validador RFC 3986. */
const URL_RE = /https?:\/\/\S+|www\.\S+/gi;

/**
 * ¿Hay que descartar por "solo emoji o sticker" (`ignore_sticker_or_emoji_only`)?
 * Dos casos bajo el mismo interruptor:
 *   - Sin texto (tras recortar) pero CON sticker: el sticker ES el mensaje.
 *   - Con texto, pero ese texto es solo emoji (unicode y/o custom).
 * Sin texto y sin sticker (por ejemplo, solo un adjunto) NO cae aquí — eso lo cubre
 * `ignore_attachment_only`, un interruptor aparte.
 */
function isStickerOrEmojiOnly(trimmedContent: string, hasStickers: boolean): boolean {
	if (trimmedContent.length === 0) return hasStickers;
	return isEmojiOnlyContent(trimmedContent);
}

/**
 * `true` = el miembro puede ganar XP con este evento (mensaje o tirada de voz).
 * Orden deliberado: primero el bypass (corta todo lo demás), luego las dos
 * antigüedades (aplican también en voz), y al final los cinco requisitos que
 * SOLO existen en texto (`ctx.message` ausente ⇒ ya se ha cumplido todo).
 */
export function meetsRequirements(reqs: DBLevelingRequirements, ctx: RequirementContext): boolean {
	// Bypass total: un rol de bypass hace que el miembro cumpla SIEMPRE, sin
	// evaluar nada más (ni siquiera la antigüedad). Staff, boosters, etc.
	if (reqs.bypass_role_ids.some((id) => ctx.roleIds.includes(id))) return true;

	if (reqs.min_membership_seconds > 0 && ctx.joinedAt !== null) {
		// Caché fría (`ctx.joinedAt === null`): esta rama ni se entra, así que el
		// requisito NO se evalúa y el miembro se concede por defecto. Es la misma
		// decisión que ya toma `resolveSessionCredit` en el ticker de voz cuando
		// no puede leer el estado de voz de una sesión (se salta el paso sin
		// penalizar): "no se pudo comprobar" no es lo mismo que "no cumple".
		// Castigar por un fallo de infraestructura (una caché de miembros que
		// aún no se ha poblado) sería peor que el abuso que este requisito busca
		// cortar. Deliberado y no obvio — no "arreglar" a un `?? 0`.
		const membershipSeconds = (Date.now() - ctx.joinedAt) / 1000;
		if (membershipSeconds < reqs.min_membership_seconds) return false;
	}

	if (reqs.min_account_age_seconds > 0) {
		const accountAgeSeconds = (Date.now() - accountCreatedAtMs(ctx.userId)) / 1000;
		if (accountAgeSeconds < reqs.min_account_age_seconds) return false;
	}

	// Todo lo que sigue es SOLO TEXTO: en voz `ctx.message` es `undefined` y no
	// hay nada más que comprobar.
	if (!ctx.message) return true;

	const { content, hasAttachments, hasStickers, prefix } = ctx.message;
	const trimmed = content.trim();

	if (reqs.min_message_length > 0 && trimmed.length < reqs.min_message_length) return false;
	if (reqs.ignore_link_only && trimmed.length > 0 && trimmed.replace(URL_RE, "").trim().length === 0) return false;
	if (reqs.ignore_attachment_only && hasAttachments && trimmed.length === 0) return false;
	if (reqs.ignore_sticker_or_emoji_only && isStickerOrEmojiOnly(trimmed, hasStickers)) return false;
	if (reqs.ignore_commands && prefix.length > 0 && trimmed.startsWith(prefix)) return false;

	return true;
}

