1	package validations
2	
3	import (
4		"kena.bot/api-db-go/internal/domain/dbguild"
5	)
6	
7	// ModuleParams matches `paramsModuleValidation` (bot_id + guild_id).
8	// Used by every music/greeter/logs handler.
9	type ModuleParams struct {
10		BotID   string `params:"bot_id"   validate:"required"`
11		GuildID string `params:"guild_id" validate:"required"`
12	}
13	
14	// ModuleMusicFieldParams adds the `:field` path segment. The field is
15	// constrained to the keys of `dbguild.ModuleMusic` at runtime by the
16	// handler — go-playground/validator cannot enforce "must be a key of this
17	// struct" without a custom tag, so the handler does the membership check
18	// after parsing.
19	type ModuleMusicFieldParams struct {
20		BotID   string `params:"bot_id"   validate:"required"`
21		GuildID string `params:"guild_id" validate:"required"`
22		Field   string `params:"field"    validate:"required"`
23	}
24	
25	// ModuleEnabledQuery matches `queryModuleEnabledValidation` in the
26	// Node service. `Module` is optional and, when present, must be one of
27	// the canonical module keys (`music | greeter | logs`). The
28	// go-playground `oneof` tag enforces the enum at bind time — unknown
29	// values produce a 400 Zod-shaped error.
30	//
31	// `tickets` is intentionally excluded from the `oneof` enum: the Node
32	// ModulesKeys array includes it, but the Node validator rejects it on
33	// the query param, and the controller has no implementation. The Go
34	// port mirrors that.
35	type ModuleEnabledQuery struct {
36		Module string `query:"module" validate:"omitempty,oneof=music greeter logs"`
37	}
38	
39	// UpdateModuleMusicBody mirrors the Node `updateModuleMusicSchema` (which
40	// is `moduleMusicSchema.partial()`). All fields are pointers so the
41	// handler can distinguish "absent" from "zero value". Only non-nil fields
42	// are forwarded into the Mongo `$set` payload.
43	//
44	// PER OLA-3 DECISION: all module PATCH bodies use `.strict()` semantics —
45	// unknown keys are rejected. The Node music body is the only one that
46	// silently drops them at the Mongoose layer; we tighten this to parity
47	// with greeter/logs (already `.strict()`).
48	type UpdateModuleMusicBody struct {
49		SchemaVersion      *int                             `json:"schema_version,omitempty"`
50		Enabled            *bool                            `json:"enabled,omitempty"`
51		MaxSongDuration    *int                             `json:"max_song_duration,omitempty"`
52		Loop               *dbguild.MusicLoop               `json:"loop,omitempty"`
53		Volume             *int                             `json:"volume,omitempty"`
54		RadioMode          *dbguild.RadioMode               `json:"radio_mode,omitempty"`
55		MessageRetention   *bool                            `json:"message_retention,omitempty"`
56		PinnedNowPlaying   *bool                            `json:"pinned_now_playing,omitempty"`
57		VoiceStatusEnabled *bool                            `json:"voice_status_enabled,omitempty"`
