package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// ModuleParams matches `paramsModuleValidation` (bot_id + guild_id).
// Used by every music/greeter/logs handler.
type ModuleParams struct {
	BotID   string `params:"bot_id"   validate:"required"`
	GuildID string `params:"guild_id" validate:"required"`
}

// ModuleMusicFieldParams adds the `:field` path segment. The field is
// constrained to the keys of `dbguild.ModuleMusic` at runtime by the
// handler — go-playground/validator cannot enforce "must be a key of this
// struct" without a custom tag, so the handler does the membership check
// after parsing.
type ModuleMusicFieldParams struct {
	BotID   string `params:"bot_id"   validate:"required"`
	GuildID string `params:"guild_id" validate:"required"`
	Field   string `params:"field"    validate:"required"`
}

// ModuleEnabledQuery matches `queryModuleEnabledValidation` in the
// Node service. `Module` is optional and, when present, must be one of
// the canonical module keys (`music | greeter | logs`). The
// go-playground `oneof` tag enforces the enum at bind time — unknown
// values produce a 400 Zod-shaped error.
//
// `tickets` is intentionally excluded from the `oneof` enum: the Node
// ModulesKeys array includes it, but the Node validator rejects it on
// the query param, and the controller has no implementation. The Go
// port mirrors that.
type ModuleEnabledQuery struct {
	Module string `query:"module" validate:"omitempty,oneof=music greeter logs"`
}

// UpdateModuleMusicBody mirrors the Node `updateModuleMusicSchema` (which
// is `moduleMusicSchema.partial()`). All fields are pointers so the
// handler can distinguish "absent" from "zero value". Only non-nil fields
// are forwarded into the Mongo `$set` payload.
//
// PER OLA-3 DECISION: all module PATCH bodies use `.strict()` semantics —
// unknown keys are rejected. The Node music body is the only one that
// silently drops them at the Mongoose layer; we tighten this to parity
// with greeter/logs (already `.strict()`).
type UpdateModuleMusicBody struct {
	SchemaVersion      *int                             `json:"schema_version,omitempty"`
	Enabled            *bool                            `json:"enabled,omitempty"`
	MaxSongDuration    *int                             `json:"max_song_duration,omitempty"`
	Loop               *dbguild.MusicLoop               `json:"loop,omitempty"`
	Volume             *int                             `json:"volume,omitempty"`
	RadioMode          *dbguild.RadioMode               `json:"radio_mode,omitempty"`
	MessageRetention   *bool                            `json:"message_retention,omitempty"`
	PinnedNowPlaying   *bool                            `json:"pinned_now_playing,omitempty"`
	VoiceStatusEnabled *bool                            `json:"voice_status_enabled,omitempty"`
	EnhancedSearch     *bool                            `json:"enhanced_search,omitempty"`
	AutoDeleteCommands *[]string                        `json:"auto_delete_commands,omitempty"`
	AudioQuality       *dbguild.MusicAudioQuality       `json:"audio_quality,omitempty" validate:"omitempty,oneof=default hifi"`
	CommandsGlobal     *dbguild.MusicCommandAccess      `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.MusicCommand `json:"commands,omitempty"`
	TextChannels       *dbguild.ChannelsConfig          `json:"text_channels,omitempty"`
	VoiceChannels      *dbguild.ChannelsConfig          `json:"voice_channels,omitempty"`
	DJ                 *dbguild.DJ                      `json:"dj,omitempty"`
	RecommendedArtists *[]string                        `json:"recommended_artists,omitempty"`
}

// Set returns the BSON document for the `$set` payload. Returns nil when
// no fields were supplied so the repository can short-circuit and avoid
// issuing a no-op update.
func (b UpdateModuleMusicBody) Set() map[string]any {
	out := map[string]any{}
	if b.SchemaVersion != nil {
		out["schema_version"] = *b.SchemaVersion
	}
	if b.Enabled != nil {
		out["enabled"] = *b.Enabled
	}
	if b.MaxSongDuration != nil {
		out["max_song_duration"] = *b.MaxSongDuration
	}
	if b.Loop != nil {
		out["loop"] = string(*b.Loop)
	}
	if b.Volume != nil {
		out["volume"] = *b.Volume
	}
	if b.RadioMode != nil {
		out["radio_mode"] = *b.RadioMode
	}
	if b.MessageRetention != nil {
		out["message_retention"] = *b.MessageRetention
	}
	if b.PinnedNowPlaying != nil {
		out["pinned_now_playing"] = *b.PinnedNowPlaying
	}
	if b.VoiceStatusEnabled != nil {
		out["voice_status_enabled"] = *b.VoiceStatusEnabled
	}
	if b.EnhancedSearch != nil {
		out["enhanced_search"] = *b.EnhancedSearch
	}
	if b.AutoDeleteCommands != nil {
		// Puntero + slice no vacío garantizado: el puntero distingue "no viene
		// en el PATCH" de "viene la lista vacía", que es un ajuste legítimo
		// ("no limpiar nada") y tiene que poder guardarse.
		list := *b.AutoDeleteCommands
		if list == nil {
			list = []string{}
		}
		out["auto_delete_commands"] = list
	}
	if b.AudioQuality != nil {
		out["audio_quality"] = string(*b.AudioQuality)
	}
	if b.CommandsGlobal != nil {
		out["commands_global"] = *b.CommandsGlobal
	}
	if b.Commands != nil {
		out["commands"] = *b.Commands
	}
	if b.TextChannels != nil {
		out["text_channels"] = *b.TextChannels
	}
	if b.VoiceChannels != nil {
		out["voice_channels"] = *b.VoiceChannels
	}
	if b.DJ != nil {
		out["dj"] = *b.DJ
	}
	if b.RecommendedArtists != nil {
		out["recommended_artists"] = *b.RecommendedArtists
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// RadioModeEnabled is a helper for the controller's PATCH side-effect
// (`redisAdapter.cache.lavalink.setPlayerPersistent`). Returns nil when the
// PATCH body omits `radio_mode` entirely; otherwise a pointer to the new value.
//
// `radio_mode` is whole-object REPLACE, not merge: its fields are values, not
// pointers, so a body carrying `radio_mode` ALWAYS sets `enabled` - omitting
// the field inside it means `false`. That is not a quirk of this helper: `Set`
// above writes that same `false` to Mongo, so the two destinations stay in
// step. The shared TS type (`library-shared/src/db/schemas/DBGuildSchemas.ts`)
// declares both fields required, so no typed client can send the partial.
func (b UpdateModuleMusicBody) RadioModeEnabled() *bool {
	if b.RadioMode == nil {
		return nil
	}
	v := b.RadioMode.Enabled
	return &v
}

