// restricción en los tres ejes, que es lo único consistente con
// `commands.rank.use_global` naciendo en `true` en los tres.
//
// `updated_at` es el epoch (`new Date(0)` en TS), como en el resto de
// módulos con `updated_at` propio (greeter, tempvoice, tts).
func NewModuleLeveling() dbguild.ModuleLeveling {
	return dbguild.ModuleLeveling{
