}

// LevelingAnnounce mirrors el objeto inline `ModuleLeveling.announce` de la
// interfaz TS. `Content` es un CENTINELA (ver `NewModuleLeveling` en el
// paquete `mocks`): mientras el guild lo tenga byte a byte igual al default
// de fábrica, bot y dashboard lo traducen con la clave i18n
// `announceDefault` — igual que `DEFAULT_TEMPVOICE_PANEL`.
type LevelingAnnounce struct {
	Enabled            bool                   `bson:"enabled"              json:"enabled"`
	Target             LevelingAnnounceTarget `bson:"target"               json:"target"`
	ChannelID          *string                `bson:"channel_id"           json:"channel_id"`
