package mocks

import (
	"time"

	"kena.bot/api-db-go/internal/domain/dbguild"
)

// levelingStr es un constructor local de *string para los defaults nullable
// del módulo de niveles (colores, contenido de texto del lienzo por
// defecto…). Privado al fichero para no colisionar con los constructores
// homólogos de otros mocks del paquete (`tempvoiceStr`, `ticketsStr`, …).
func levelingStr(s string) *string { return &s }

// levelingFloat es el gemelo de `levelingStr` para los floats nullable del
// lienzo por defecto (tamaño de letra, radio, valor de muestra de la
// barra…).
func levelingFloat(f float64) *float64 { return &f }

// levelingInt es el gemelo de `levelingStr` para los enteros nullable
// (grosor de letra).
func levelingInt(i int) *int { return &i }

// levelingCommandAccessDefault: sin restricción en los tres ejes. El módulo
// de niveles no tiene el caso especial de tempvoice (canal ceñido al recién
// creado): `rank` es un comando de lectura sin canal propio, así que el
// default global es simplemente "todos". Slices nuevos en cada llamada para
// que dos documentos no compartan el mismo array.
func levelingCommandAccessDefault() dbguild.LevelingCommandAccess {
	return dbguild.LevelingCommandAccess{
		Roles:      dbguild.LevelingAccessList{Mode: dbguild.LevelingAccessAllExcept, IDs: []string{}},
		Channels:   dbguild.LevelingAccessList{Mode: dbguild.LevelingAccessAllExcept, IDs: []string{}},
		Categories: dbguild.LevelingAccessList{Mode: dbguild.LevelingAccessAllExcept, IDs: []string{}},
	}
}

// levelingConfigurableCommandDefault: activo y heredando el acceso global en
// los tres ejes — el único comando del módulo (`rank`) nace así.
func levelingConfigurableCommandDefault() dbguild.LevelingCommand {
	return dbguild.LevelingCommand{
		Enabled:   true,
		UseGlobal: dbguild.LevelingCommandSync{Roles: true, Channels: true, Categories: true},
		Access:    levelingCommandAccessDefault(),
	}
}

// defaultLevelingCardCanvas mirrors `DEFAULT_LEVELING_CARD_CANVAS` en
// DBGuildSchemas.ts CAMPO A CAMPO — no es un diseño libre: cualquier
// coordenada, id de elemento o tamaño de letra que se desvíe de ese literal
// TS es un bug. Es el lienzo 934×282 que ve el usuario la primera vez que
// pasa `rank_card.mode` a `"advanced"`: avatar circular a la izquierda;
// nombre, nivel y puesto arriba a la derecha; debajo una barra de progreso
// (`bar_token: "progress"`) y el contador de XP del nivel actual. Aloja una
// porción fresca en cada llamada para que dos documentos nunca compartan el
// mismo slice.
func defaultLevelingCardCanvas() dbguild.GreeterImageCanvas {
	return dbguild.GreeterImageCanvas{
		Width:           934,
		Height:          282,
		BackgroundColor: levelingStr("#1e1f22"),
		BackgroundURL:   nil,
		BackgroundFit:   nil,
		Elements: []dbguild.GreeterImageElement{
			{
				ID:      "avatar",
				Type:    "avatar",
				Name:    "Avatar",
				X:       41,
				Y:       41,
				Width:   200,
				Height:  200,
				Opacity: 1,
				URL:     nil,
				Radius:  levelingFloat(100),
				Fit:     levelingStr("cover"),
			},
			{
				ID:         "username",
				Type:       "text",
				Name:       "Usuario",
				X:          281,
				Y:          44,
				Width:      500,
				Height:     50,
				Opacity:    1,
				Content:    levelingStr("{user}"),
				Color:      levelingStr("#ffffff"),
				FontSize:   levelingFloat(40),
				FontWeight: levelingInt(700),
				TextAlign:  levelingStr("left"),
			},
			{
				ID:         "level",
				Type:       "text",
				Name:       "Nivel",
				X:          281,
				Y:          104,
				Width:      300,
				Height:     36,
				Opacity:    1,
				Content:    levelingStr("NIVEL {level}"),
				Color:      levelingStr("#5865F2"),
				FontSize:   levelingFloat(26),
				FontWeight: levelingInt(600),
				TextAlign:  levelingStr("left"),
			},
			{
				ID:         "rank",
				Type:       "text",
				Name:       "Puesto",
				X:          700,
				Y:          104,
				Width:      180,
				Height:     36,
				Opacity:    1,
				Content:    levelingStr("#{rank}"),
				Color:      levelingStr("#ffffff"),
				FontSize:   levelingFloat(26),
				FontWeight: levelingInt(600),
				TextAlign:  levelingStr("right"),
			},
			{
				ID:       "progress-bar",
				Type:     "bar",
				Name:     "Barra de progreso",
				X:        281,
				Y:        168,
				Width:    599,
				Height:   26,
				Opacity:  1,
				Fill:     levelingStr("#5865F2"),
				Color:    levelingStr("#3a3c42"),
				Radius:   levelingFloat(100),
				BarToken: levelingStr("progress"),
				BarValue: levelingFloat(45),
			},
			{
				ID:         "xp-text",
				Type:       "text",
				Name:       "XP",
				X:          281,
				Y:          204,
				Width:      599,
				Height:     30,
				Opacity:    1,
				Content:    levelingStr("{xp} / {xp_needed}"),
				Color:      levelingStr("#b5bac1"),
				FontSize:   levelingFloat(18),
				FontWeight: levelingInt(400),
				TextAlign:  levelingStr("left"),
			},
		},
	}
}

// NewModuleLeveling son los DEFAULTS de fábrica del módulo de niveles —
// espejo campo a campo de `DEFAULT_LEVELING_*` en DBGuildSchemas.ts (§5 de
// la spec del lote). Un default que falte aquí es deriva silenciosa de datos
// en la primera escritura, así que este fichero tiene que ir en paralelo con
// el TS: si tocas uno, toca el otro.
//
// `announce.content` es el CENTINELA — mientras el guild lo conserve BYTE A
// BYTE igual a este literal, bot y dashboard lo traducen con la clave i18n
// `announceDefault` en vez de mostrarlo tal cual (mismo contrato que
// `DEFAULT_TEMPVOICE_PANEL`). Si cambias este string, coordínalo con el TS o
// el centinela deja de reconocerse en los guilds ya creados.
//
// `commands_global` no aparece explícito en el bloque de defaults de la spec
// (§5): se mirror-ea el criterio de `TTSCommandAccessDefault` — sin
// restricción en los tres ejes, que es lo único consistente con
// `commands.rank.use_global` naciendo en `true` en los tres.
//
// `updated_at` es el epoch (`new Date(0)` en TS), como en el resto de
// módulos con `updated_at` propio (greeter, tempvoice, tts).
func NewModuleLeveling() dbguild.ModuleLeveling {
	return dbguild.ModuleLeveling{
		SchemaVersion: dbguild.SchemaVersionLeveling,
		Enabled:       false,
		EnabledSince:  nil,
		XPMode:        dbguild.LevelingXPModeUnified,
		Text: dbguild.LevelingXpSource{
			Enabled:         true,
			Min:             15,
			Max:             25,
			IntervalSeconds: 60,
		},
		Voice: dbguild.LevelingXpSource{
			Enabled:         true,
			Min:             5,
			Max:             10,
			IntervalSeconds: 60,
		},
		CurveMultiplier: 1,
		VoiceRules: dbguild.LevelingVoiceRules{
			IgnoreAlone:    true,
			IgnoreMuted:    true,
			IgnoreDeafened: true,
		},
		ExcludedChannelIDs: []string{},
		ExcludedRoleIDs:    []string{},
		RoleMultipliers:    []dbguild.LevelingMultiplier{},
		ChannelMultipliers: []dbguild.LevelingMultiplier{},
		Announce: dbguild.LevelingAnnounce{
			Enabled:            true,
			Target:             dbguild.LevelingAnnounceTargetCurrent,
			ChannelID:          nil,
			Content:            "¡{mention} ha subido al nivel **{level}**!",
			DeleteAfterSeconds: nil,
		},
		Rewards: dbguild.LevelingRewards{
			Enabled:  false,
			Stacking: dbguild.LevelingRewardStackingStack,
			Levels:   []dbguild.LevelingReward{},
		},
		RankCard: dbguild.LevelingRankCard{
			Mode:          dbguild.LevelingCardBasic,
			BackgroundURL: nil,
			AccentColor:   "#5865F2",
			Canvas:        defaultLevelingCardCanvas(),
		},
		CommandsGlobal: levelingCommandAccessDefault(),
		Commands: map[string]dbguild.LevelingCommand{
			"rank": levelingConfigurableCommandDefault(),
		},
		CommandMode: dbguild.LevelingCommandModeBoth,
		UpdatedAt:   dbguild.NewDate(time.Unix(0, 0).UTC()),
	}
}

