package dbguild

import "testing"

// TestNormalizeLeveling_NilReceiver — defensivo, igual que NormalizeGreeter.
func TestNormalizeLeveling_NilReceiver(t *testing.T) {
	NormalizeLeveling(nil) // no debe entrar en pánico
}

// TestNormalizeLeveling_RequirementsBypassRoleIDs — un documento legacy (o
// una entrada de caché vieja, anterior al bloque de requisitos) decodifica
// `text.requirements.bypass_role_ids`/`voice.requirements.bypass_role_ids`
// como `nil`. NormalizeLeveling tiene que dejarlos en `[]string{}` para que
// el JSON emita `[]`, nunca `null` — mismo invariante que
// `excluded_channel_ids`/`excluded_role_ids`.
func TestNormalizeLeveling_RequirementsBypassRoleIDs(t *testing.T) {
	m := ModuleLeveling{
		SchemaVersion: SchemaVersionLeveling,
		Text:          LevelingXpSource{Requirements: LevelingRequirements{BypassRoleIDs: nil}},
		Voice:         LevelingXpSource{Requirements: LevelingRequirements{BypassRoleIDs: nil}},
	}

	NormalizeLeveling(&m)

	if m.Text.Requirements.BypassRoleIDs == nil {
		t.Fatal("text.requirements.bypass_role_ids sigue nil (emitiría null en JSON)")
	}
	if len(m.Text.Requirements.BypassRoleIDs) != 0 {
		t.Fatalf("text.requirements.bypass_role_ids = %v, want []", m.Text.Requirements.BypassRoleIDs)
	}
	if m.Voice.Requirements.BypassRoleIDs == nil {
		t.Fatal("voice.requirements.bypass_role_ids sigue nil (emitiría null en JSON)")
	}
	if len(m.Voice.Requirements.BypassRoleIDs) != 0 {
		t.Fatalf("voice.requirements.bypass_role_ids = %v, want []", m.Voice.Requirements.BypassRoleIDs)
	}
}

