}

// LevelingCommandAccess mirrors `DBCommandAccess` — acceso por eje (quién:
// roles, dónde: canales/categorías) del comando `rank`.
type LevelingCommandAccess struct {
	Roles      LevelingAccessList `bson:"roles"      json:"roles"`
	Channels   LevelingAccessList `bson:"channels"   json:"channels"`
